//! The PS3.6 data dictionary and UID registry, and the PS3.15 de-identification table.
//!
//! The tables are generated by `scripts/update-dicom-dict.py` from the DocBook XML of the DICOM
//! standard (edition [`EDITION`]; sources, digests and licence in `crates/cameleer-dicom/DICTIONARY.md`)
//! into `dict_data.rs` (module `data`) and `deid_table.rs` (module [`deid`]). Never edit them
//! by hand.
//!
//! Data elements come from PS3.6 Tables 6-1 (data elements), 7-1 (file meta), 8-1 (directory
//! structuring) and 9-1 (dynamic RTP payload), and the command elements of group 0000 from PS3.7
//! Tables E.1-1 and E.2-1 (the latter retired). Not included: private tags (odd groups, always
//! `None`), group length tags `(gggg,0000)` other than those the standard lists (`(0000,0000)`,
//! `(0002,0000)`), the item and delimiter tags `(FFFE,E000)`, `(FFFE,E00D)`, `(FFFE,E0DD)` (no VR;
//! the codec handles them), and retired placeholders that PS3.6 lists without a name or VR.

use crate::vr::{Vr, ALL};

#[path = "dict_data.rs"]
#[rustfmt::skip]
mod data;

/// PS3.15 Table E.1-1 (Application Level Confidentiality Profile Attributes).
#[path = "deid_table.rs"]
#[rustfmt::skip]
pub mod deid;

/// The edition of the standard the tables come from (`2026d`).
pub const EDITION: &str = data::EDITION;

/// One data element of the dictionary.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Entry {
    /// The tag, `(group << 16) | element`. For repeating groups and ranges such as
    /// `(60xx,3000)` or `(0028,04x0)` the `x` digits are zero here and cleared in `mask`.
    pub tag: u32,
    /// Bits of a tag that must equal `tag` for this entry to apply (`0xFFFF_FFFF` for a
    /// plain tag, `0xFF00_FFFF` for `(60xx,3000)`).
    pub mask: u32,
    /// The VR (the first one where PS3.6 lists several, such as `US or SS`).
    pub vr: Vr,
    /// The second VR where PS3.6 lists two (`US or SS`, `OB or OW`).
    pub alt_vr: Option<Vr>,
    /// Value multiplicity as written in PS3.6 (`1`, `1-n`, `2-2n`...).
    pub vm: &'static str,
    /// The keyword (`PatientID`).
    pub keyword: &'static str,
    /// The attribute name (`Patient ID`).
    pub name: &'static str,
    /// Retired in the current edition.
    pub retired: bool,
}

fn blob(b: &'static str, r: u32) -> &'static str {
    let off = (r >> 8) as usize;
    &b[off..off + (r & 0xFF) as usize]
}

fn entry(e: &data::E) -> Entry {
    Entry {
        tag: e.tag,
        mask: e.mask,
        vr: ALL[e.vr as usize],
        alt_vr: if e.alt == 255 { None } else { Some(ALL[e.alt as usize]) },
        vm: data::VMS[e.vm as usize],
        keyword: blob(data::KEYWORDS, e.kw),
        name: blob(data::NAMES, e.name),
        retired: e.retired,
    }
}

fn by_index(i: usize) -> &'static data::E {
    let n = data::ELEMENTS.len();
    if i < n {
        &data::ELEMENTS[i]
    } else {
        &data::MASKED[i - n]
    }
}

/// The entry for a tag, exact entries first, then repeating groups and ranges. Private tags
/// (odd groups) give `None`.
pub fn lookup(tag: u32) -> Option<Entry> {
    if (tag >> 16) & 1 == 1 {
        return None;
    }
    if let Ok(i) = data::ELEMENTS.binary_search_by_key(&tag, |e| e.tag) {
        return Some(entry(&data::ELEMENTS[i]));
    }
    data::MASKED.iter().find(|e| tag & e.mask == e.tag).map(entry)
}

/// The entry for a keyword.
pub fn by_keyword(keyword: &str) -> Option<Entry> {
    let idx = data::KEYWORD_INDEX;
    idx.binary_search_by(|&i| blob(data::KEYWORDS, by_index(i as usize).kw).cmp(keyword))
        .ok()
        .map(|k| entry(by_index(idx[k] as usize)))
}

/// The keyword of a tag (`None` for private and unknown tags).
pub fn keyword(tag: u32) -> Option<&'static str> {
    lookup(tag).map(|e| e.keyword)
}

/// The number of data elements in the dictionary (plain tags plus repeating groups).
pub fn len() -> usize {
    data::ELEMENTS.len() + data::MASKED.len()
}

/// The kind of a registered UID.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum UidKind {
    SopClass,
    TransferSyntax,
    MetaSopClass,
    WellKnownSopInstance,
    ApplicationContextName,
    CodingScheme,
    Other,
}

/// One entry of the PS3.6 UID registry (Table A-1).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct UidEntry {
    pub uid: &'static str,
    pub name: &'static str,
    pub keyword: &'static str,
    pub kind: UidKind,
    pub retired: bool,
}

fn uid_entry(t: &(&'static str, &'static str, &'static str, UidKind, bool)) -> UidEntry {
    UidEntry { uid: t.0, name: t.1, keyword: t.2, kind: t.3, retired: t.4 }
}

/// The registry entry for a UID.
pub fn uid(uid: &str) -> Option<UidEntry> {
    data::UIDS.binary_search_by(|t| t.0.cmp(uid)).ok().map(|i| uid_entry(&data::UIDS[i]))
}

/// The registry entry for a UID keyword (`CTImageStorage`).
pub fn uid_by_keyword(keyword: &str) -> Option<UidEntry> {
    data::UIDS.iter().find(|t| t.2 == keyword).map(uid_entry)
}

/// Every registered UID of a kind (for example all Storage SOP classes are the
/// [`UidKind::SopClass`] entries whose name ends in `Storage`).
pub fn uids(kind: UidKind) -> Vec<UidEntry> {
    data::UIDS.iter().filter(|t| t.3 == kind).map(uid_entry).collect()
}

/// The rows of PS3.15 Table E.1-1 that apply to a tag, in the table's order. Several rows can
/// match one tag (a plain row and a repeating-group row, or a private tag and the
/// `(gggg,eeee)` row); prefer the row with the most `mask` bits.
pub fn deid_rows(tag: u32) -> impl Iterator<Item = &'static deid::DeidRow> {
    deid::ROWS.iter().filter(move |r| tag & r.mask == r.tag & r.mask)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn data_elements() {
        let e = lookup(0x0010_0020).unwrap();
        assert_eq!((e.keyword, e.name, e.vr, e.vm, e.retired), ("PatientID", "Patient ID", Vr::LO, "1", false));
        let px = lookup(0x7FE0_0010).unwrap();
        assert_eq!((px.keyword, px.vr, px.alt_vr), ("PixelData", Vr::OB, Some(Vr::OW)));
        let ov = lookup(0x6002_3000).unwrap();
        assert_eq!((ov.keyword, ov.tag, ov.mask), ("OverlayData", 0x6000_3000, 0xFF00_FFFF));
        assert_eq!(by_keyword("OverlayData").unwrap().tag, 0x6000_3000);
        let ts = by_keyword("TransferSyntaxUID").unwrap();
        assert_eq!((ts.tag, ts.vr), (0x0002_0010, Vr::UI));
        let cf = lookup(0x0000_0100).unwrap();
        assert_eq!((cf.keyword, cf.vr), ("CommandField", Vr::US));
        assert_eq!(by_keyword("SpecificCharacterSet").unwrap().tag, 0x0008_0005);
        assert_eq!(by_keyword("NoSuchKeyword"), None);
        assert_eq!(lookup(0x0009_0010), None, "private tags have no entry");
        assert_eq!(lookup(0x0028_0010).unwrap().vr, Vr::US);
        assert_eq!(lookup(0x0028_0106).unwrap().alt_vr, Some(Vr::SS));
        assert_eq!(keyword(0x0020_000D), Some("StudyInstanceUID"));
        assert!(len() > 4000, "{}", len());
        // every keyword resolves back to its own entry
        for i in 0..len() {
            let e = entry(by_index(i));
            assert_eq!(by_keyword(e.keyword).map(|f| f.keyword), Some(e.keyword));
        }
        assert_eq!(EDITION, "2026d");
    }

    #[test]
    fn uid_registry() {
        let u = uid("1.2.840.10008.1.2").unwrap();
        assert_eq!(u.kind, UidKind::TransferSyntax);
        assert!(u.name.starts_with("Implicit VR Little Endian"), "{}", u.name);
        let ct = uid_by_keyword("CTImageStorage").unwrap();
        assert_eq!((ct.uid, ct.kind), ("1.2.840.10008.5.1.4.1.1.2", UidKind::SopClass));
        assert!(uid("1.2.840.10008.1.2.2").unwrap().retired);
        assert_eq!(uid("1.2.3.4"), None);
        assert!(uids(UidKind::SopClass).iter().filter(|u| u.name.ends_with("Storage")).count() > 100);
        assert!(uids(UidKind::TransferSyntax).iter().any(|u| u.uid == "1.2.840.10008.1.2.1.99"));
    }

    #[test]
    fn deid_table() {
        let pn: Vec<_> = deid_rows(0x0010_0010).collect();
        assert_eq!(pn[0].basic, "Z");
        assert_eq!(pn[0].name, "Patient's Name");
        let study = deid_rows(0x0020_000D).next().unwrap();
        assert_eq!((study.basic, study.retain_uids), ("U", "K"));
        let date = deid_rows(0x0008_0022).next().unwrap();
        assert_eq!((date.basic, date.retain_long_full_dates, date.retain_long_modified_dates), ("X/Z", "K", "C"));
        // the private-group row matches any odd group
        assert!(deid_rows(0x0009_1001).any(|r| r.name.starts_with("Private")));
        assert!(deid_rows(0x6002_3000).any(|r| r.basic == "X"));
        assert!(deid::ROWS.len() > 600);
        assert_eq!(deid::EDITION, "2026d");
    }
}
